            let nScalars = 0;

            this.data.forEach(element => POLYNOMIAL === element.type ? nPolynomials++ : nScalars++);

            let buffer = new Uint8Array(nScalars * this.Fr.n8 + nPolynomials * this.G1.F.n8 * 2);
